UPDATE mall_user_coupon
SET status = 1, order_no = #{orderNo}, lock_time = #{now}
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted = 0
  AND status = 0
  AND (forever = 1 OR (expire_time IS NOT NULL AND expire_time > #{now}))

UPDATE mall_user_coupon
SET status = 2, use_time = #{now}
WHERE order_no = #{orderNo} AND status = 1 AND deleted = 0
